SELECT CASE WHEN YEAR(signup_date) < 2024 THEN 'before_2024' WHEN YEAR(signup_date) = 2024 THEN '2024' ELSE 'after_2024' END AS signup_cohort, COUNT(CASE WHEN segment = 'Consumer' THEN 1 END) AS consumer_count, SUM(CASE WHEN segment = 'Corporate' THEN 1 ELSE 0 END) AS corporate_count FROM customers WHERE (UPPER(email) LIKE '%IAM%' AND segment = 'Corporate') OR UPPER(TRIM(name)) = 'GRACE KIM' GROUP BY 1 HAVING SUM(CASE WHEN segment = 'Corporate' THEN 1 ELSE 0 END) < 78 ORDER BY corporate_count DESC
